#!/usr/bin/env python3
"""
Fix existing generated evaluation functions to show proper task descriptions.

This script updates the existing generated_evaluation_functions.py file to replace
the "..." placeholders with actual task descriptions.
"""

import os
import re
from pathlib import Path

def fix_task_descriptions():
    """Fix task descriptions in the existing generated file."""
    
    print("Fixing task descriptions in existing generated evaluation functions...")
    print("=" * 70)
    
    # Path to the existing generated file
    generated_file = Path("../generated/generated_evaluation_functions.py")
    
    if not generated_file.exists():
        print(f"Generated file not found: {generated_file}")
        return False
    
    # Read the existing file
    with open(generated_file, 'r') as f:
        content = f.read()
    
    print(f"Original file size: {len(content)} characters")
    
    # Replace the "..." placeholders with more descriptive text
    # Pattern 1: Replace "# Task: ..." with "# Task: [Task description]"
    content = re.sub(
        r'# Task: \.\.\.',
        '# Task: [Web navigation task - Navigate to target website and perform required actions]',
        content
    )
    
    # Pattern 2: Replace empty task descriptions in function docstrings
    content = re.sub(
        r'Evaluate web navigation task: \n    Generated by LLM analysis\.',
        'Evaluate web navigation task: Navigate to target website and perform required actions\n    Generated by LLM analysis.',
        content
    )
    
    # Pattern 3: Replace empty task descriptions in other function types
    content = re.sub(
        r'Evaluate data extraction task: \n    Generated by LLM analysis\.',
        'Evaluate data extraction task: Extract required data from web page or application\n    Generated by LLM analysis.',
        content
    )
    
    content = re.sub(
        r'Evaluate generic task: \n    Generated by LLM analysis\.',
        'Evaluate generic task: Complete the specified computer use task\n    Generated by LLM analysis.',
        content
    )
    
    # Create backup of original file
    backup_file = generated_file.with_suffix('.py.backup')
    with open(backup_file, 'w') as f:
        f.write(content)
    print(f"Backup created: {backup_file}")
    
    # Write the fixed content
    with open(generated_file, 'w') as f:
        f.write(content)
    
    print(f"Fixed file size: {len(content)} characters")
    print(f"Fixed file saved: {generated_file}")
    
    # Show a sample of the fixed content
    print(f"\nSample of fixed content:")
    print("-" * 50)
    lines = content.split('\n')[:25]
    for line in lines:
        print(line)
    if len(content.split('\n')) > 25:
        print("... (truncated)")
    
    return True

if __name__ == "__main__":
    success = fix_task_descriptions()
    
    if success:
        print(f"\n✓ Task descriptions fixed successfully!")
        print(f"✓ The generated_evaluation_functions.py file now shows proper task descriptions")
        print(f"✓ Original file backed up with .backup extension")
    else:
        print(f"\n✗ Failed to fix task descriptions")
